def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(write_time, current_time):
        return current_time >= write_time + ttl

    def clean_expired(current_time):
        # Remove expired entries
        keys_to_delete = []
        for key, (value, write_time) in cache.items():
            if is_expired(write_time, current_time):
                keys_to_delete.append(key)
        for key in keys_to_delete:
            del cache[key]

    for op in ops:
        if op[0] == 'put':
            t, key, value = op[1], op[2], op[3]
            clean_expired(t)

            # If key exists, remove it first (to re-insert at end for LRU)
            if key in cache:
                del cache[key]
            # If cache is full and key is new, evict LRU
            elif len(cache) >= capacity:
                # Remove the first item (least recently used)
                cache.popitem(last=False)

            # Insert the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            t, key = op[1], op[2]
            clean_expired(t)

            if key in cache:
                value, write_time = cache[key]
                # Mark as most recently used by moving to end
                del cache[key]
                cache[key] = (value, write_time)
                results.append(value)
            else:
                results.append(-1)

    return results

